CREATE POLICY "upload own plan images" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='plan-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN('jpg','jpeg','png','webp'));
CREATE POLICY "read own uploaded plan images" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='plan-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "remove own uploaded plan images" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='plan-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE TABLE public.plan_photo_registry(photo text PRIMARY KEY,plan_id uuid NOT NULL REFERENCES public.plans(id) ON DELETE CASCADE);
GRANT ALL ON public.plan_photo_registry TO service_role; ALTER TABLE public.plan_photo_registry ENABLE ROW LEVEL SECURITY;
INSERT INTO public.plan_photo_registry(photo,plan_id) SELECT unnest(photos),id FROM public.plans WHERE cardinality(photos)>0;
CREATE FUNCTION public.register_plan_gallery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE url text; BEGIN IF cardinality(NEW.photos)>0 AND (cardinality(NEW.photos)<3 OR cardinality(NEW.photos)>5 OR cardinality(NEW.photos)<>(SELECT count(DISTINCT x) FROM unnest(NEW.photos) x)) THEN RAISE EXCEPTION 'Add 3 to 5 distinct event photos.'; END IF; IF TG_OP='UPDATE' AND NEW.photos=OLD.photos THEN RETURN NEW; END IF; DELETE FROM public.plan_photo_registry WHERE plan_id=NEW.id; FOREACH url IN ARRAY NEW.photos LOOP IF url LIKE 'storage:%' AND url NOT LIKE 'storage:plan-photos/'||NEW.host_id::text||'/%' THEN RAISE EXCEPTION 'Use your own uploaded photographs.'; END IF; INSERT INTO public.plan_photo_registry(photo,plan_id) VALUES(url,NEW.id); END LOOP; RETURN NEW; END $$;
CREATE TRIGGER register_plan_gallery AFTER INSERT OR UPDATE OF photos ON public.plans FOR EACH ROW EXECUTE FUNCTION public.register_plan_gallery();
CREATE OR REPLACE FUNCTION public.is_plan_member(_plan uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.plans p WHERE p.id=_plan AND (p.host_id=_user OR (public.org_access(p.organisation_id,_user) AND ((p.is_private AND _user=ANY(p.private_participants)) OR EXISTS(SELECT 1 FROM public.join_requests j WHERE j.plan_id=p.id AND j.user_id=_user AND j.status='approved'))))) $$;
CREATE OR REPLACE FUNCTION public.get_plan_address(_plan uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.plans; result text; BEGIN SELECT * INTO p FROM public.plans WHERE id=_plan; IF auth.uid() IS NULL OR p.id IS NULL THEN RETURN NULL; END IF; IF p.host_id<>auth.uid() AND (NOT public.org_access(p.organisation_id,auth.uid()) OR NOT public.is_plan_member(_plan,auth.uid()) OR now()<p.starts_at-interval '2 hours') THEN RETURN NULL; END IF; SELECT address INTO result FROM public.plan_addresses WHERE plan_id=_plan; RETURN result; END $$;